      {
          sprite.sSlideSpeed += sprite.sSlideAccel;
          sprite.x = sprite.sSlideSpeed >> 4;
      }
      else
      {
          sprite.x = sprite.sSlideEndX;
          sprite.callback = SpriteCallbackDummy;
      }
